set client_min_messages=warning;
create or replace function pg_temp.recipe() returns jsonb language sql immutable as $$select '{"version":"sf-sdxl-recommended-v1","mode":"recommended","settings":{"resolution":[1024,1024],"enable_bucket":true,"min_bucket_reso":512,"max_bucket_reso":1024,"bucket_reso_steps":64,"train_batch_size":1,"learning_rate":0.0001,"network_module":"networks.lora","network_dim":64,"network_alpha":32,"mixed_precision":"fp16","gradient_checkpointing":true,"save_model_as":"safetensors","save_every_n_steps":200,"target_effective_samples":1200,"caption_extension":".txt","caption_model":"Salesforce/blip-image-captioning-base","trigger_suffix":"woman"}}'::jsonb$$;
create or replace function pg_temp.payload(job uuid, identity uuid, snapshot jsonb default '{"dataset_ready":true,"accepted_count":2}'::jsonb) returns jsonb language sql stable as $$select jsonb_build_object('identity_id',identity::text,'dataset_doctor_job_id',job::text,'dataset_reference',jsonb_build_object('bucket','datasets','prefix','final/a'),'dataset_snapshot',snapshot,'dataset_selection',jsonb_build_object('image_ids',jsonb_build_array('40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002'),'image_count',2),'trainer_recipe',pg_temp.recipe())$$;
create or replace function pg_temp.expect_error(expected text,owner_id uuid,lora_id uuid,payload jsonb,bucket text default 'datasets',prefix text default 'final/a',fingerprint text default repeat('a',64),key text default 'rejected') returns void language plpgsql as $$begin perform public.submit_trainer_compute_job(owner_id,lora_id,key,fingerprint,payload,'standard',bucket,prefix); raise exception 'EXPECTED_FAILURE_NOT_RAISED:%',expected; exception when others then if sqlerrm not like expected||'%' then raise exception 'EXPECTED_%,GOT_%',expected,sqlerrm; end if; end$$;

do $$ declare t text; begin
 foreach t in array array['dataset_doctor_jobs','dataset_doctor_images','dataset_doctor_selections'] loop
  assert not has_table_privilege('anon','public.'||t,'select'); assert not has_table_privilege('anon','public.'||t,'insert'); assert not has_table_privilege('anon','public.'||t,'update'); assert not has_table_privilege('anon','public.'||t,'delete');
  assert not has_table_privilege('authenticated','public.'||t,'select'); assert not has_table_privilege('authenticated','public.'||t,'insert'); assert not has_table_privilege('authenticated','public.'||t,'update'); assert not has_table_privilege('authenticated','public.'||t,'delete');
  assert has_table_privilege('service_role','public.'||t,'select,insert,update,delete');
 end loop;
 assert not has_table_privilege('anon','public.user_loras','select'); assert not has_table_privilege('anon','public.user_loras','insert'); assert not has_table_privilege('anon','public.user_loras','update'); assert not has_table_privilege('anon','public.user_loras','delete');
 assert has_table_privilege('authenticated','public.user_loras','select'); assert not has_table_privilege('authenticated','public.user_loras','insert'); assert not has_table_privilege('authenticated','public.user_loras','update'); assert not has_table_privilege('authenticated','public.user_loras','delete'); assert has_table_privilege('service_role','public.user_loras','select,insert,update,delete');
 assert has_function_privilege('service_role','public.submit_trainer_compute_job(uuid,uuid,text,text,jsonb,text,text,text)','execute'); assert not has_function_privilege('authenticated','public.submit_trainer_compute_job(uuid,uuid,text,text,jsonb,text,text,text)','execute'); assert not has_function_privilege('anon','public.submit_trainer_compute_job(uuid,uuid,text,text,jsonb,text,text,text)','execute'); assert not exists(select 1 from aclexplode((select proacl from pg_proc where oid='public.submit_trainer_compute_job(uuid,uuid,text,text,jsonb,text,text,text)'::regprocedure))a where grantee=0 and privilege_type='EXECUTE');
 assert to_regprocedure('public.finalize_trainer_compute_job(uuid,uuid,uuid,text,text)') is not null; assert to_regprocedure('public.finalize_recovered_trainer_compute_job(uuid,uuid,uuid,uuid,text,text,bigint,bigint,text)') is not null; assert to_regclass('public.video_projects') is not null; assert to_regprocedure('public.video_compute_manifest(uuid,uuid,uuid)') is not null; assert to_regprocedure('public.stitch_compute_manifest(uuid,uuid,uuid)') is not null; assert to_regprocedure('public.finalize_video_compute_job(uuid,uuid,uuid,jsonb)') is not null; assert to_regprocedure('public.finalize_stitch_compute_job(uuid,uuid,uuid,jsonb)') is not null; assert to_regclass('public.compute_jobs_active_owner_idx') is not null; assert to_regclass('public.compute_jobs_one_active_owner_workload_idx') is not null;
end$$;

